package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class TakeDropWhileTest {

    @Test
    void prefixBasedVsFilter() {
        List<Integer> prices = List.of(100, 102, 101, 95, 110);
        int floor = 100;

        assertThat(prices.stream().takeWhile(p -> p >= floor).toList())
            .containsExactly(100, 102, 101);                 // stops at 95
        assertThat(prices.stream().dropWhile(p -> p >= floor).toList())
            .containsExactly(95, 110);                       // from first dip
        assertThat(prices.stream().filter(p -> p >= floor).toList())
            .containsExactly(100, 102, 101, 110);            // tests ALL
    }
}
